-- B1 plan: 8 lessons (library, published). Written by hand; each lesson uses library tasks and practice.
-- Idempotent by title; position = order in the B1 plan.
insert into public.study_lessons (author_id, scope, status, title, description, cefr, topic, duration_min, source, position, content)
select (select id from public.profiles where role = 'admin' order by created_at limit 1), 'library', 'published', v.title, v.description, 'B1', v.topic, v.duration, 'manual', v.pos, v.content::jsonb
from (values
(
  'Have you ever…?', 'Talk about experiences and news with the Present Perfect, and switch to the Past Simple for the details.', 'Culture', 55, 0,
  $json${"stages": [
    {"kind": "warmup", "title": "Find someone who has…", "minutes": 6,
     "teacher": "Students walk around and ask “Have you ever…?” questions (been on TV, met someone famous, eaten something strange, lost your phone). When someone says yes, they ask one follow-up question in the Past Simple.",
     "body": "Ask your classmates “Have you ever…?”. If someone says yes, ask: When? Where? What happened?",
     "examples": ["Have you ever met someone famous? — Yes, I have!", "Who did you meet? — I met a footballer at the airport."], "task_id": null},
    {"kind": "presentation", "title": "Present Perfect or Past Simple?", "minutes": 12,
     "teacher": "Draw a timeline. Present Perfect: the time is not said or not finished, the result matters now. Past Simple: a finished time (yesterday, last year, in 2020, ago). Show the typical pattern: start with the Present Perfect, then give details in the Past Simple.",
     "body": "**Present Perfect** (have / has + past participle) — experience or news, **no finished time**:\nI**’ve been** to Italy. She**’s** just **posted** a new video. Have you **ever** tried sushi?\nWords: ever, never, just, already, yet, so far, since, for.\n\n**Past Simple** — a **finished time**:\nI **went** to Italy **last summer**. She **posted** it **an hour ago**.\nWords: yesterday, last…, …ago, in 2020, when I was…\n\n**Typical pattern:** news / experience → details\n— I**’ve passed** my driving test! — Wow! When **did** you **take** it? — I **took** it on Monday.",
     "examples": ["I’ve never seen the sea.", "Have you finished the series yet? — Yes, I finished it last night.", "We’ve known each other since 2019.", "She lost her keys yesterday, and she still hasn’t found them."], "task_id": null},
    {"kind": "tasks", "title": "Practice: Present Perfect", "minutes": 8,
     "teacher": "A warm-up practice of the form. Check irregular past participles: been, seen, done, gone, eaten.",
     "body": "Write or choose the Present Perfect.", "examples": [], "task_id": "20ad67aa-c28b-45bd-87f0-2acd6259952d"},
    {"kind": "tasks", "title": "Practice: Present Perfect or Past Simple?", "minutes": 10,
     "teacher": "For each answer students say the reason: is there a finished time or not?",
     "body": "Choose the right tense.", "examples": [], "task_id": "cc45c9ea-65c1-4a30-a7a3-330ab38a9afd"},
    {"kind": "practice", "title": "Reading: The Blue Door café", "minutes": 8,
     "teacher": "Read the review. Students find one Present Perfect and one Past Simple sentence and explain the difference.",
     "body": "Read the café review and answer the questions.", "examples": [], "task_id": "300665e5-df43-4877-8187-1f6d7c004ead"},
    {"kind": "production", "title": "Two truths and a lie", "minutes": 9,
     "teacher": "Each student says three experiences (Present Perfect), one is a lie. The others ask Past Simple questions to find the lie.",
     "body": "Say 3 sentences about your experiences — 2 true, 1 false. Your classmates ask questions to find the lie.",
     "examples": ["I’ve been to three concerts this year.", "When did you go? Who did you see? Who did you go with?"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 2,
     "teacher": "Explain the homework.",
     "body": "Write a short review (100–120 words) of a place, game or series you’ve tried recently: start with your experience (Present Perfect) and then tell what happened (Past Simple).",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'It was raining when…', 'Tell stories with the Past Continuous for the background and the Past Simple for the events.', 'Culture', 50, 1,
  $json${"stages": [
    {"kind": "warmup", "title": "Where were you?", "minutes": 5,
     "teacher": "Ask: What were you doing yesterday at 8 pm? At midnight? At 7 am? Students answer quickly, then ask a partner.",
     "body": "What were you doing yesterday at 8 pm? At midnight? This morning at 7?",
     "examples": ["At 8 pm I was watching a stream.", "At midnight I was sleeping… probably."], "task_id": null},
    {"kind": "presentation", "title": "Background and events", "minutes": 10,
     "teacher": "Draw a long wavy line (Past Continuous — background) cut by a short arrow (Past Simple — event). Show when + Past Simple and while + Past Continuous.",
     "body": "**Past Continuous** (was / were + -ing) — an action **in progress** at a moment in the past, the **background** of a story:\nIt **was raining**. People **were rushing** home.\n**Past Simple** — the **events**, what happened next:\nSuddenly the lights **went out**.\n\nTogether: I **was walking** home **when** I **saw** a dog.\n**While** I **was walking** home, I **saw** a dog.\nStates (know, want, like) don’t usually take -ing: I **knew** (not I was knowing).",
     "examples": ["I was having a shower when the doorbell rang.", "While we were waiting for the bus, it started to snow.", "What were you doing when I called you?"], "task_id": null},
    {"kind": "tasks", "title": "Practice: Past Continuous", "minutes": 12,
     "teacher": "Students do the exercises. Ask: background or event?",
     "body": "Choose the Past Continuous or the Past Simple.", "examples": [], "task_id": "6ffaf11a-341c-4c77-becc-831a21436842"},
    {"kind": "practice", "title": "Reading: The dog at the supermarket", "minutes": 10,
     "teacher": "Read the story. Students underline the background (Past Continuous) in one colour and the events (Past Simple) in another.",
     "body": "Read the story and answer the questions.", "examples": [], "task_id": "822c81d4-b2d9-47a4-b4d6-75309e46caaf"},
    {"kind": "production", "title": "Chain story", "minutes": 10,
     "teacher": "Start a story: “It was a dark and stormy night. I was walking home when…”. Each student adds one sentence: background or event. Keep it fun and kind.",
     "body": "Make a story together, one sentence each. Use was / were + -ing for the background and the Past Simple for what happened.",
     "examples": ["I was walking home when my phone died.", "While I was looking for a charger, someone tapped my shoulder…"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write a short story (120 words) that starts with: “I was … when …”. It can be true or invented.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'I used to…', 'Talk about past habits and how things have changed with used to and didn’t use to.', 'Transport', 50, 2,
  $json${"stages": [
    {"kind": "warmup", "title": "Childhood confessions", "minutes": 5,
     "teacher": "Tell one funny thing you did as a child (e.g. you thought the moon followed your car). Students share their own.",
     "body": "What did you do or believe when you were a child? Share one funny thing.",
     "examples": ["I thought the moon was following me.", "I was scared of the hair dryer."], "task_id": null},
    {"kind": "presentation", "title": "Used to", "minutes": 10,
     "teacher": "Show that used to is for habits and states that are not true now. Questions and negatives: did + use to (no -d). Contrast with be used to (= be accustomed) only briefly.",
     "body": "**used to + verb** — a past habit or state that is **not true now**:\nI **used to** play the piano. (I don’t now.)\nThere **used to** be a cinema here.\n**Negative:** I **didn’t use to** like coffee.\n**Question:** **Did** you **use to** have long hair?\nNot for one action: I **went** to Paris in 2019 (not used to go).\n**Careful:** I’m **used to** getting up early = it’s normal for me (a different meaning).",
     "examples": ["I used to watch cartoons every morning before school.", "We didn’t use to have a dog.", "Did you use to play outside a lot?", "My town used to be much quieter."], "task_id": null},
    {"kind": "tasks", "title": "Practice: used to", "minutes": 12,
     "teacher": "Students do the exercises. Check use / used in questions and negatives.",
     "body": "Choose or write used to / didn’t use to.", "examples": [], "task_id": "2e6058a0-f105-48d9-8ef2-73830157d4d9"},
    {"kind": "practice", "title": "Listening: Life without a car", "minutes": 10,
     "teacher": "Play the podcast twice. Students note how Sara’s life used to be and how it is now.",
     "body": "Listen to the podcast and answer the questions.", "examples": [], "task_id": "0cece79d-c98a-44ed-adb3-d20d76325495"},
    {"kind": "production", "title": "How times have changed", "minutes": 10,
     "teacher": "Groups compare how people used to do things and how they do them now: listening to music, meeting friends, studying, shopping, taking photos. Each group presents the most surprising change.",
     "body": "Compare the past and today: music, friends, studying, shopping, photos. What did people use to do?",
     "examples": ["People used to buy CDs. Now everyone uses streaming.", "My parents didn’t use to have phones at school."], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework. Interviewing a grandparent or parent is a great option.",
     "body": "Ask a parent or grandparent about their teenage years and write 8 sentences with used to / didn’t use to.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'If I were you…', 'Imagine and give advice with the second conditional, and compare it with real possibilities (first conditional).', 'Daily Life', 55, 3,
  $json${"stages": [
    {"kind": "warmup", "title": "Would you rather…?", "minutes": 6,
     "teacher": "Ask fun “Would you rather…?” questions: be able to fly or be invisible? live without music or without the internet? Students answer with “I’d rather…, because…”.",
     "body": "Would you rather fly or be invisible? Live without music or without the internet? Why?",
     "examples": ["I’d rather fly, because I’d never be late.", "I’d rather live without… hmm, that’s hard."], "task_id": null},
    {"kind": "presentation", "title": "Real or imaginary?", "minutes": 12,
     "teacher": "Put two sentences on the board: “If it rains, I’ll stay home” (real, possible) and “If I won a million, I’d travel the world” (imaginary). Show the forms and that there is no would in the if part.",
     "body": "**First conditional** — **real** possibility:\n**If** + Present Simple, **will** + verb: If it **rains**, I**’ll** stay home.\n\n**Second conditional** — **imaginary or unlikely** (now / future):\n**If** + Past Simple, **would** + verb: If I **had** a million dollars, I**’d** travel the world.\n**Advice:** **If I were you**, I’d talk to her.\n**Questions:** What **would** you **do** if you **were** invisible?\n**No would after if:** If I ~~would have~~ **had** time…",
     "examples": ["If I were you, I’d apologise.", "If I could speak five languages, I’d work at the UN.", "If you finish early, we’ll go to the cinema.", "What would you do if you lost your phone?"], "task_id": null},
    {"kind": "tasks", "title": "Practice: second conditional", "minutes": 12,
     "teacher": "Students do the exercises. For each answer ask: real or imaginary?",
     "body": "Choose or write the right form.", "examples": [], "task_id": "469d1ba2-a615-4556-8d93-627a573c018b"},
    {"kind": "practice", "title": "Practice: first conditional", "minutes": 8,
     "teacher": "A contrast practice: these situations are real and possible.",
     "body": "Choose or write the first conditional.", "examples": [], "task_id": "917c7627-3e9e-4d21-9ff6-9f33e0eb778d"},
    {"kind": "production", "title": "Advice column", "minutes": 14,
     "teacher": "Give each pair a short problem card (my friend copies my homework; I spend 8 hours a day on my phone; I want to start a YouTube channel but I’m shy). Pairs write advice with “If I were you…”, then read it to the class; the class votes for the best advice.",
     "body": "Read the problem and give advice with “If I were you, I’d…”. Then imagine: what would happen if they followed your advice?",
     "examples": ["If I were you, I’d turn off notifications after 9 pm.", "If you started the channel, you’d get more confident."], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write 6 “What would you do if…?” questions, answer them yourself, and ask a friend or family member to answer too.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'Made in…: the passive', 'Talk about how things are made, invented and done with the passive: is made, was invented, by whom.', 'Basic Words', 50, 4,
  $json${"stages": [
    {"kind": "warmup", "title": "Where is it from?", "minutes": 6,
     "teacher": "Students check labels on their things (phone, hoodie, shoes, snacks) and say where they were made. Write a few answers on the board in the passive.",
     "body": "Look at your phone, clothes or snacks. Where were they made?",
     "examples": ["My hoodie was made in Bangladesh.", "This phone was designed in the USA."], "task_id": null},
    {"kind": "presentation", "title": "The passive", "minutes": 12,
     "teacher": "Show that the passive puts the focus on the thing or action, not the person. Form: be + past participle. Use by only when the doer matters.",
     "body": "**Active:** Someone **stole** my bike. → **Passive:** My bike **was stolen**.\n**Form:** be + past participle\nPresent: English **is spoken** here. These phones **are made** in China.\nPast: The bridge **was built** in 1890. The tickets **were sold** in an hour.\n**by** + the doer, only if it is important: The song **was written by** a 16-year-old.\nWe use the passive when the doer is unknown, obvious or not important — in news, facts and instructions.",
     "examples": ["The first iPhone was released in 2007.", "My phone was stolen on the bus.", "Pizza is eaten all over the world.", "The film was directed by a young woman from Kyiv."], "task_id": null},
    {"kind": "tasks", "title": "Practice: the passive", "minutes": 14,
     "teacher": "Students do the exercises. Pay attention to irregular past participles: made, written, built, stolen, eaten.",
     "body": "Choose or write the passive.", "examples": [], "task_id": "68b7fcfe-9853-44ae-9a9f-df91e2ff4601"},
    {"kind": "production", "title": "Quiz time", "minutes": 15,
     "teacher": "Groups write 5 quiz questions in the passive about inventions, songs, films, buildings or games (When was … invented? Who was … written by? Where are … made?). Groups swap and answer. Allow phones for checking only after answering.",
     "body": "Write 5 quiz questions with the passive. Swap with another group and answer their questions.",
     "examples": ["When was the first video game made?", "Who was “Harry Potter” written by?", "Where are most smartphones made?"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Choose an object you use every day and write its “biography” (100 words): where and when it was made, how it was used, what happened to it. Use the passive at least 5 times.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'The person who…', 'Describe people, things and places precisely with who, which, that, where and whose.', 'Daily Life', 50, 5,
  $json${"stages": [
    {"kind": "warmup", "title": "Guess the word", "minutes": 6,
     "teacher": "Describe words without saying them: “It’s a person who cooks in a restaurant.” “It’s a thing which keeps food cold.” Students guess. Then they make their own.",
     "body": "Listen and guess the word. Then describe a word for your partner.",
     "examples": ["It’s a person who cooks in a restaurant. — A chef!", "It’s a place where you watch films. — A cinema!"], "task_id": null},
    {"kind": "presentation", "title": "Relative clauses", "minutes": 10,
     "teacher": "Show the relative pronouns and that they replace he / she / it — we don’t add an extra pronoun. Show that who / which / that can be dropped when they are the object.",
     "body": "**who** — people: She’s the girl **who** won the competition.\n**which** — things: This is the app **which** I use every day.\n**that** — people or things (informal): The film **that** we watched was scary.\n**where** — places: That’s the café **where** we met.\n**whose** — possession: The boy **whose** phone was stolen.\nNo extra pronoun: the book which I read ~~it~~.\nYou can drop who / which / that when it is the object: The film (that) we watched…",
     "examples": ["A zookeeper is a person who looks after animals.", "That’s the song which was everywhere last summer.", "The town where I grew up is very small.", "I have a friend whose mum is a pilot."], "task_id": null},
    {"kind": "tasks", "title": "Practice: who, which, that", "minutes": 12,
     "teacher": "Students do the exercises. Ask: person, thing or place?",
     "body": "Choose the right relative pronoun.", "examples": [], "task_id": "7640ee13-3cfe-41dd-997a-797040421178"},
    {"kind": "practice", "title": "Listening: A day at the zoo", "minutes": 10,
     "teacher": "Play the interview twice. Students write 3 sentences about the job with who / which / where.",
     "body": "Listen to the interview with a zookeeper and answer the questions.", "examples": [], "task_id": "cd8c9fac-940b-49fc-82c5-41740b4c6a05"},
    {"kind": "production", "title": "Taboo", "minutes": 10,
     "teacher": "Play Taboo: a student describes a word from a card using relative clauses, without saying the word. Their team guesses. Use words from the students’ world: influencer, playlist, charger, best friend, gym.",
     "body": "Describe the word on your card with who, which, that or where. Your team guesses!",
     "examples": ["It’s a person who has a lot of followers and posts every day.", "It’s a thing which you need when your battery is low."], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 2,
     "teacher": "Explain the homework.",
     "body": "Write 8 definitions of words from your hobby for your own mini-dictionary, using who, which, that or where.",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'I enjoy doing, I want to do', 'Use the right form after verbs: -ing (enjoy, avoid, finish) or to + verb (want, decide, hope).', 'Culture', 50, 6,
  $json${"stages": [
    {"kind": "warmup", "title": "Likes and plans", "minutes": 6,
     "teacher": "Ask: What do you enjoy doing at the weekend? What do you want to learn this year? Write the answers on the board in two columns without explaining yet.",
     "body": "Answer: What do you enjoy doing at the weekend? What do you want to learn this year?",
     "examples": ["I enjoy sleeping late.", "I want to learn to drive."], "task_id": null},
    {"kind": "presentation", "title": "-ing or to + verb?", "minutes": 12,
     "teacher": "Use the two columns from the warm-up. Give memory tricks: -ing verbs often describe what is going on or what you feel about it (enjoy, mind, finish); to-verbs often look forward (want, hope, plan, decide). Show -ing after prepositions and -ing as the subject.",
     "body": "**Verb + -ing:** enjoy, finish, avoid, mind, keep, can’t stand, spend time\nI **enjoy reading**. Do you **mind waiting**?\n**Verb + to + verb:** want, decide, hope, plan, promise, need, learn, would like\nShe **decided to quit** the team. I **hope to see** you soon.\n**After a preposition → -ing:** good **at drawing**, interested **in learning**, **before leaving**.\n**-ing as the subject:** **Swimming** is good for you.\n**Different meaning:** I **stopped to eat** (to have food) / I **stopped eating** (no more food).",
     "examples": ["I can’t stand waiting in queues.", "We’re planning to start a band.", "She’s really good at editing videos.", "Learning a language takes time."], "task_id": null},
    {"kind": "tasks", "title": "Practice: doing or to do?", "minutes": 14,
     "teacher": "Students do the exercises. For each answer ask: which verb comes first?",
     "body": "Choose the -ing form or to + verb.", "examples": [], "task_id": "e9325135-25bb-4aba-a3b0-3e636baabf03"},
    {"kind": "production", "title": "Personality test", "minutes": 15,
     "teacher": "Pairs write a fun 6-question personality test (Do you enjoy…? Would you like to…? Are you good at…? Do you mind…?). They test another pair and give a funny result.",
     "body": "Write a 6-question personality test with enjoy, mind, want, would like, good at… Test another pair and tell them their result.",
     "examples": ["Do you enjoy meeting new people?", "Would you like to live abroad?", "Result: you’re a calm explorer who hates waiting!"], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write your “bucket list” for this year: 5 things you want / hope / plan to do and 5 things you enjoy or can’t stand doing (10 sentences).",
     "examples": [], "task_id": null}
  ]}$json$
),
(
  'You should try it', 'Give and ask for advice with should, shouldn’t and ought to — politely and clearly.', 'Health', 50, 7,
  $json${"stages": [
    {"kind": "warmup", "title": "Life hacks", "minutes": 5,
     "teacher": "Ask students to share one life hack (for studying, sleeping, saving money). Write a few on the board as should-sentences.",
     "body": "Share one useful life hack: studying, sleeping, saving money or staying calm.",
     "examples": ["Put your phone in another room when you study.", "Drink water before coffee."], "task_id": null},
    {"kind": "presentation", "title": "Should and ought to", "minutes": 10,
     "teacher": "Show that should gives advice (softer than must). No to after should. Show softeners: I think you should…, Maybe you should…, and asking for advice: Should I…? What do you think I should do?",
     "body": "**should + verb** — advice, a good idea: You **should** sleep more.\n**shouldn’t** — not a good idea: You **shouldn’t** post your address online.\n**ought to** = should (less common): We **ought to** leave now.\n**Asking for advice:** **Should** I tell her? What do you think I **should** do?\n**Softer:** I think you should… / Maybe you should… / If I were you, I’d…\n**should** = advice; **must / have to** = rule or necessity.\nNo to after should: You should ~~to~~ go.",
     "examples": ["You should try the new café — it’s amazing.", "You shouldn’t study all night before an exam.", "Should I buy the blue one or the black one?", "Maybe you should talk to your teacher."], "task_id": null},
    {"kind": "tasks", "title": "Practice: should / shouldn’t", "minutes": 12,
     "teacher": "Students do the exercises. Ask them to make one piece of advice for the class after each answer.",
     "body": "Choose or write should, shouldn’t or ought to.", "examples": [], "task_id": "2bedde68-88c1-4c86-8aa9-c09788cb5033"},
    {"kind": "practice", "title": "Reading: Why a short nap is good for you", "minutes": 10,
     "teacher": "Read the article. Students write 3 pieces of advice from the text with should / shouldn’t.",
     "body": "Read the article and answer the questions.", "examples": [], "task_id": "716c5f0e-7846-4664-9cca-66c8b2cc26c8"},
    {"kind": "production", "title": "Ask Lean", "minutes": 10,
     "teacher": "Students write a short anonymous problem (exam stress, a fight with a friend, no motivation). Mix them up. Each student reads one and gives kind advice with should and I think you should… The class adds one more idea.",
     "body": "Read a classmate’s problem and give kind advice: I think you should… / You shouldn’t… / Maybe you should…",
     "examples": ["I think you should make a short plan for each day.", "You shouldn’t compare yourself with others."], "task_id": null},
    {"kind": "homework", "title": "Homework", "minutes": 3,
     "teacher": "Explain the homework.",
     "body": "Write a guide “How to survive exam week” (8–10 pieces of advice with should / shouldn’t / ought to).",
     "examples": [], "task_id": null}
  ]}$json$
)
) as v(title, description, topic, duration, pos, content)
where not exists (select 1 from public.study_lessons s where s.title = v.title and s.scope = 'library');
